'use strict';
const $=id=>document.getElementById(id);
let token=document.querySelector('meta[name="request-token"]').content;
let apps=[],profiles=[],steps=[],fixtures=[],current=null,rid=null,developer=false,copyInputId=null,pollTimer=null;
let selectionGeneration=0,newestRevision=new Map(),selectedInspector={stage:'',attempt:'',item:''},runEditState=new Map(),liveRunId=null,summaryTimer=null,summaryGeneration=0,runRows=[],activeInspectionTab='input',activeRhsTab='output',selectedCall='',selectedRetry='';
let inspectorFormat='yaml';
function yamlValue(v,indent=0){
  const pad=' '.repeat(indent),scalar=x=>x===null?'null':typeof x==='string'?JSON.stringify(x):String(x);
  if(Array.isArray(v))return v.length?v.map(x=>typeof x==='object'&&x!==null?`${pad}-\n${yamlValue(x,indent+2)}`:`${pad}- ${scalar(x)}`).join('\n'):`${pad}[]`;
  if(v&&typeof v==='object'){const entries=Object.entries(v);return entries.length?entries.map(([key,x])=>typeof x==='object'&&x!==null?`${pad}${JSON.stringify(key)}:\n${yamlValue(x,indent+2)}`:`${pad}${JSON.stringify(key)}: ${scalar(x)}`).join('\n'):`${pad}{}`}
  return pad+scalar(v)
}
const structured=value=>inspectorFormat==='json'?JSON.stringify(value,null,2):yamlValue(value);
function rhs(which,tab){
  if(which==='clinical'){
    if(tab==='review'&&$('rhs-review-tab').disabled)tab='output';
    activeRhsTab=tab;
    const output=$('run-output');
    if(tab==='review')$('review-output').append(output);
    else $('review').before(output);
    $('run-input').hidden=tab!=='input';output.hidden=tab==='input';
    $('review').hidden=tab!=='review';$('review-output').hidden=tab!=='review';
    for(const name of ['input','output','review']){$(`rhs-${name}-tab`).classList.toggle('active',name===tab);$(`rhs-${name}-tab`).setAttribute('aria-selected',String(name===tab))}
  }else{
    $('dev-run-input').hidden=tab!=='input';$('dev-run-output').hidden=tab!=='output';
    for(const name of ['input','output']){$(`dev-${name}-tab`).classList.toggle('active',name===tab);$(`dev-${name}-tab`).setAttribute('aria-selected',String(name===tab))}
  }
}

function showError(err,persistent=true){
  const data=err?.data?.error||err?.error||null;
  const parts=[];
  if(data){parts.push(data.explanation||data.code||'Request failed');if(data.detail&&['provider_request_rejected','authentication_rejected','provider_transient_failure'].includes(data.code))parts.push(`Provider detail: ${data.detail}`);if(data.remedy)parts.push(data.remedy);if(data.diagnostic_reference)parts.push(`Diagnostic: ${data.diagnostic_reference}`)}
  else parts.push(err?.message||String(err));
  $('error-text').replaceChildren(document.createTextNode(parts.filter(Boolean).join(' — ')));if(data){const details=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');summary.textContent='Details';pre.textContent=yamlValue(data);details.append(summary,pre);$('error-text').append(details)}$('error').hidden=false;$('error').dataset.persistent=persistent?'1':'0';
}
function clearError(force=false){if(force||$('error').dataset.persistent!=='1'){$('error').hidden=true;$('error-text').textContent=''}}
async function api(path,data,method){
  const opts={method:method||(data===undefined?'GET':'POST'),headers:{}};
  if(data!==undefined){opts.headers['Content-Type']='application/json';opts.headers['X-LocalMedBot-Token']=token;opts.body=JSON.stringify(data)}
  if(opts.method==='DELETE')opts.headers['X-LocalMedBot-Token']=token;
  const r=await fetch(path,opts);let out={};try{out=await r.json()}catch(_){out={}}
  if(!r.ok){const e=new Error(out?.error?.code||`HTTP ${r.status}`);e.data=out;throw e}return out;
}
const guard=fn=>async(...a)=>{try{clearError();await fn(...a)}catch(e){showError(e)}};
const parseJson=(id,fallback)=>{const t=$(id).value.trim();if(!t)return fallback;try{return JSON.parse(t)}catch(_){throw new Error(`${id}: invalid JSON`)}};
const workflow=()=> $('workflow').value;
function retryOverrides(){const out={};for(const [id,key] of [['repair-override','output_repair_retries'],['semantic-override','semantic_revision_retries']]){const v=$(id)?.value;if(v!==undefined&&v!==''){const n=Number(v);if(!Number.isInteger(n)||n<0)throw new Error(`${key} must be a non-negative integer`);out[key]=n}}return out}

function switchWorkspace(which){$('workspace-selector').value=which;$('clinical-workspace').hidden=which!=='clinical';$('developer-workspace').hidden=which!=='developer';if(current)render(current)}
function showDevPane(which){for(const n of ['full','step','guidelines']){$(`dev-${n}`).hidden=n!==which;$(`dev-tab-${n}`).classList.toggle('active',n===which)}}

async function loadProfiles(){
  profiles=await api('/api/model-profiles?workflow_id='+encodeURIComponent(workflow()));
  const prev=$('profile').value;$('profile').replaceChildren(...profiles.map(p=>new Option(p.name,p.id)));if(profiles.some(p=>p.id===prev))$('profile').value=prev;else{const chosen=profiles.find(p=>p.selected)||profiles[0];if(chosen)$('profile').value=chosen.id}
  $('step-profile').replaceChildren(...profiles.map(p=>new Option(p.name,p.id)));if($('profile').value)$('step-profile').value=$('profile').value;showProfile();
}
function reasoningChoices(executor){if(executor==='openrouter')return ['default','none','minimal','low','medium','high','xhigh'];if(executor==='lmstudio')return ['default','none','low','medium','high'];return ['default']}
function profileOverrides(){const out={base_url:$('base-url').value,model:$('model').value,settings:{reasoning:$('reasoning').value||'default'}};return out}
function showProfile(){const p=profiles.find(x=>x.id===$('profile').value);if(!p)return;$('base-url').value=p.base_url||'';$('model').value=p.model||'';$('credential').value='';const selected=p.settings?.reasoning||'default';$('reasoning').replaceChildren(...reasoningChoices(p.executor).map(v=>new Option(v[0].toUpperCase()+v.slice(1),v)));$('reasoning').value=reasoningChoices(p.executor).includes(selected)?selected:'default';$('reasoning').disabled=!['openrouter','lmstudio'].includes(p.executor);const d=p.destination||{};$('destination').textContent=`${p.executor} · ${p.model||'model not set'} · ${d.classification||'destination unknown'}${p.credential_present?' · credential present':''}`}
async function saveProfile(){const p=profiles.find(x=>x.id===$('profile').value);if(!p)return;const overlay=profileOverrides();if(!overlay.base_url.trim())delete overlay.base_url;if(!overlay.model.trim())delete overlay.model;const body={profile_id:p.id,overlay};if($('credential').value)body.credential=$('credential').value;await api('/api/model-profiles/configure',body);await loadProfiles();$('verify-result').textContent='Settings saved.'}
async function verifyProvider(){const r=await api('/api/providers/verify',{profile_id:$('profile').value,workflow_id:workflow(),profile_overrides:profileOverrides()});$('verify-result').textContent=(r.success?'Verification succeeded.':'Verification failed. Check the selected provider settings. ')+ '\n'+yamlValue(r)}

async function chooseWorkflow(){
  await loadProfiles();const app=apps.find(a=>a.id===workflow());const previous=$('purpose').value;$('purpose').replaceChildren(...(app?.purposes?.options||[]).map(x=>new Option(x.label,x.id)));$('purpose').value=(app?.purposes?.options||[]).some(x=>x.id===previous)?previous:app?.purposes?.default||'';$('example').replaceChildren(...(app?.examples||[]).map(x=>new Option(x,x)));await loadSets();await loadSteps();showInputs();
  $('step-workflow').value=workflow();
}
async function chooseDevWorkflow(){const app=apps.find(x=>x.id===$('dev-workflow').value),rows=await api('/api/model-profiles?workflow_id='+encodeURIComponent(app.id));$('dev-profile').replaceChildren(...rows.map(x=>new Option(x.name,x.id)));$('dev-example').replaceChildren(...(app.examples||[]).map(x=>new Option(x,x)));$('dev-purpose').replaceChildren(...(app.purposes?.options||[]).map(x=>new Option(x.label,x.id)));$('dev-purpose').value=app.purposes?.default||'';const sets=app.id==='guideline_qa'?await api('/api/guideline-sets'):[];$('dev-guideline-set').replaceChildren(...sets.map(x=>new Option(x.name,x.id)));if(sets.length)await chooseDevVersions();showDevInputs()}
async function chooseDevVersions(){const sets=await api('/api/guideline-sets'),row=sets.find(x=>x.id===$('dev-guideline-set').value),values=[...(row?.releases||[])];if(developer&&!values.includes('devel'))values.push('devel');$('dev-guideline-version').replaceChildren(...values.map(x=>new Option(x,x)));if(row?.default_release)$('dev-guideline-version').value=row.default_release}
function showDevInputs(){const w=$('dev-workflow').value,mode=$('dev-input-mode').value;$('dev-demo').hidden=mode!=='demo';$('dev-purpose-field').hidden=$('dev-notes-field').hidden=mode!=='free_text'||w!=='clinical_letter';$('dev-question-field').hidden=mode!=='free_text'||w!=='guideline_qa';$('dev-guideline-fields').hidden=w!=='guideline_qa';$('dev-advanced-field').hidden=mode!=='advanced'}
async function startDevRun(){const w=$('dev-workflow').value,mode=$('dev-input-mode').value,input=mode==='advanced'?parseJson('dev-advanced-input',{}):mode==='free_text'?(w==='clinical_letter'?{notes:$('dev-notes').value,purpose:$('dev-purpose').value}:{question:$('dev-question').value}):{};const payload={workflow_id:w,profile_id:$('dev-profile').value,input_mode:mode,input,title:$('dev-run-title').value};if(mode==='demo')payload.example=$('dev-example').value;if(w==='guideline_qa')payload.guideline_selection={set_id:$('dev-guideline-set').value,selector:$('dev-guideline-version').value};const overrides=retryOverrides();if(Object.keys(overrides).length)payload.retry_overrides=overrides;const r=await api('/api/runs',payload);liveRunId=r.id;summaryGeneration++;selectRun(r.id);await refresh(r.id,selectionGeneration)}
function showInputs(){const mode=$('input-mode').value,w=workflow();$('demo-fields').hidden=mode!=='demo';$('copied-fields').hidden=mode!=='copied';$('letter-fields').hidden=!(mode==='free_text'&&w==='clinical_letter');$('qa-fields').hidden=!(mode==='free_text'&&w==='guideline_qa');$('advanced-fields').hidden=mode!=='advanced';$('start').textContent=w==='clinical_letter'?'Generate letter':'Run workflow'}
async function loadSets(){if(workflow()!=='guideline_qa')return;const sets=await api('/api/guideline-sets');const prev=$('guideline-set').value;$('guideline-set').replaceChildren(...sets.map(x=>new Option(x.name,x.id)));if(sets.some(x=>x.id===prev))$('guideline-set').value=prev;else if(sets[0])$('guideline-set').value=sets[0].id;showVersions(sets)}
async function showVersions(rows){if(workflow()!=='guideline_qa')return;const sets=rows||await api('/api/guideline-sets');const row=sets.find(x=>x.id===$('guideline-set').value);const vals=[...(row?.releases||[])];if(developer&&!vals.includes('devel'))vals.push('devel');$('guideline-version').replaceChildren(...vals.map(v=>new Option(v,v)));if(row?.default_release)$('guideline-version').value=row.default_release}

async function startRun(){
  const mode=$('input-mode').value;let input={};if(mode==='free_text')input=workflow()==='clinical_letter'?{notes:$('notes').value,purpose:$('purpose').value}:{question:$('question').value};else if(mode==='advanced')input=parseJson('advanced-input',{});
  const payload={workflow_id:workflow(),profile_id:$('profile').value,input_mode:mode,input,profile_overrides:profileOverrides(),title:$('run-title-input').value};
  if(mode==='demo')payload.example=$('example').value;if(mode==='copied')payload.copy_input_id=copyInputId;if(workflow()==='guideline_qa')payload.guideline_selection={set_id:$('guideline-set').value,selector:$('guideline-version').value};if(developer){const o=retryOverrides();if(Object.keys(o).length)payload.retry_overrides=o}
  const r=await api('/api/runs',payload);liveRunId=r.id;summaryGeneration++;selectRun(r.id);await refresh(r.id,selectionGeneration);
}
const runDay=r=>r.created?new Date(r.created*1000).toLocaleDateString('en-CA',{year:'numeric',month:'2-digit',day:'2-digit'}):'Unknown date';
function historyDates(prefer=''){const wf=$('run-workflow-filter').value,rows=runRows.filter(r=>String(r.workflow_id||'')===wf),dates=[...new Set(rows.map(runDay))];$('run-date-filter').replaceChildren(...dates.map(x=>new Option(x,x)));$('run-date-filter').value=dates.includes(prefer)?prefer:(dates[0]||'');historyTitles()}
function historyTitles(){const rows=runRows.filter(r=>String(r.workflow_id||'')===$('run-workflow-filter').value&&runDay(r)===$('run-date-filter').value),previous=$('run-select').value;$('run-select').replaceChildren(new Option('Select a run',''),...rows.map(r=>new Option(`${r.title||'Untitled'} · ${r.created?new Date(r.created*1000).toLocaleTimeString():'time unknown'} · ${r.status} · ${r.id.slice(-8)}`,r.id)));$('run-select').value=rows.some(r=>r.id===previous)?previous:rows.some(r=>r.id===rid)?rid:''}
function historySelection(){const row=runRows.find(r=>r.id===rid);if(!row){historyDates($('run-date-filter').value);return}const wf=String(row.workflow_id||'');if($('run-workflow-filter').value!==wf){$('run-workflow-filter').value=wf;historyDates(runDay(row))}else if($('run-date-filter').value!==runDay(row))historyDates(runDay(row));else historyTitles()}
async function listRuns(){const generation=summaryGeneration,rows=await api('/api/runs');if(generation!==summaryGeneration)return;runRows=rows;const filter=$('run-workflow-filter'),previous=filter.value,workflows=[...new Map([...apps.map(a=>[a.id,a.name]),...rows.map(r=>[String(r.workflow_id||''),r.application||'Legacy run'])]).entries()];filter.replaceChildren(...workflows.map(([id,name])=>new Option(name,id)));filter.value=workflows.some(([id])=>id===previous)?previous:workflows.some(([id])=>id===workflow())?workflow():(workflows[0]?.[0]||'');historyDates($('run-date-filter').value);const live=rows.find(r=>r.id===liveRunId&&['pending','running','waiting_model','waiting_review'].includes(r.status));const box=$('live-run');box.replaceChildren();if(live){const button=document.createElement('button');button.type='button';button.className='secondary';button.textContent=`Active run: ${live.title||live.application} · ${live.status} · Return to live`;button.onclick=()=>{selectRun(live.id);refresh(live.id,selectionGeneration).catch(showError)};box.append(button)}else if(liveRunId){const row=rows.find(r=>r.id===liveRunId);box.textContent=row?`Last active run: ${row.title||row.application} · ${row.status}`:'';if(!row)liveRunId=null}}
async function pollSummaries(){try{await listRuns()}catch(e){$('poll-status').hidden=false;$('poll-status').textContent=`Run list refresh failed: ${e.message}. Displayed state may be stale.`}finally{summaryTimer=setTimeout(pollSummaries,1100)}}
function selectRun(id){rid=id;selectionGeneration++;current=null;selectedCall='';selectedRetry='';clearTimeout(pollTimer);newestRevision.set(id,newestRevision.get(id)??-1);historySelection()}

function statusLabel(run,data){if(run.status==='waiting_model')return 'Waiting for self response';if(run.status==='waiting_review')return 'Waiting for human review';if(run.status==='blocked')return 'Blocked';if(run.status==='failed')return 'Failed — action required';if(run.status==='completed')return 'Completed';if(run.status==='cancelled')return 'Cancelled';const repair=(data.repairs||[]).filter(x=>['pending','in_progress'].includes(x.outcome)).at(-1);if(repair)return `Retrying output · ${repair.repair_ordinal}/${repair.frozen_limit}`;return run.status==='running'?'Executing':'Queued'}
function liveElapsed(data){let seconds=Number(data.run?.usage?.seconds||0);if(data.run?.status==='running'){const c=(data.physical_calls||[]).filter(x=>x.status==='dispatching'&&x.started_at).at(-1);if(c)seconds+=Math.max(0,Date.now()/1000-Number(c.started_at))}return seconds}
function nextActor(run){if(run.status==='waiting_model')return 'self response';if(run.status==='waiting_review')return 'human review';if(run.status==='failed'||run.status==='blocked')return 'operator action';if(run.status==='completed'||run.status==='cancelled')return 'none';return 'runtime / model'}
function updateActivity(data){const label=statusLabel(data.run,data);$('status').textContent=label;$('status').dataset.state=data.run.status;$('activity').textContent=`${label} · active ${liveElapsed(data).toFixed(1)}s · next: ${nextActor(data.run)}`}
function renderUsage(u){const values=[['Operations',u.logical_operations],['HTTP calls',u.physical_calls],['Self handoffs',u.self_handoffs],['Output repairs',u.output_repairs],['Semantic revisions',u.semantic_revisions],['Transport retries',u.transport_retries]];const tok=u.usage?.totals?.total_tokens,cost=u.usage?.totals?.cost,currency=u.usage?.totals?.currency;values.push(['Tokens',tok==null?'Unavailable':`${tok}${u.usage?.partial?' (partial)':''}`]);if(cost!=null)values.push(['Reported cost',`${cost} ${currency||''}`.trim()]);$('usage-summary').replaceChildren(...values.map(([k,v])=>{const d=document.createElement('div');d.className='metric';d.innerHTML=`<strong>${v??0}</strong>${k}`;return d}))}
function renderSteps(run,data){const progress=data.execution||{},retrying=new Set((data.repairs||[]).filter(x=>['pending','in_progress'].includes(x.outcome)).map(x=>x.node_id));$('progress-label').textContent=`Model stages reached: ${progress.reached_count||0} / ${progress.total||0} · Current: ${progress.current_node||progress.system_failure||'none'} · ${run.status}. Reached does not mean currently valid or approved.${data.inspection_degraded?' Inspection degraded: a committed artifact is unavailable.':''}`;$('progress-rail').value=progress.reached_count||0;$('progress-rail').max=progress.total||1;$('steps').replaceChildren(...(progress.stages||[]).map(stage=>{const x=document.createElement('span');x.className='step-pill';x.dataset.state=retrying.has(stage.id)?'retrying':stage.state;x.textContent=`${stage.id}: ${stage.reached?'reached':'not reached'} · ${stage.valid?'valid':stage.state}`;return x}));if(progress.system_failure){const x=document.createElement('span');x.className='step-pill';x.dataset.state='failed';x.textContent=`System step: ${progress.system_failure} · ${run.status}`;$('steps').append(x)}}
function inspectionTab(tab){activeInspectionTab=tab;for(const [name,id] of [['input','model-input-panel'],['output','model-output-panel'],['retries','retry-history'],['details','run-details']]){$(id).hidden=name!==tab;$(`tab-${name}`).classList.toggle('active',name===tab);$(`tab-${name}`).setAttribute('aria-selected',String(name===tab))}}
function detailField(box,label,value){const heading=document.createElement('strong');heading.textContent=label;box.append(heading,readable(value))}
function renderMessages(box,messages){const heading=document.createElement('strong');heading.textContent='Actual input / messages sent';box.append(heading);if(!Array.isArray(messages)){box.append(readable(messages??'Input was not recorded.'));return}for(const [i,message] of messages.entries()){const label=document.createElement('div');label.className='hint';label.textContent=`Message ${i+1} · ${message?.role||'role not recorded'}`;box.append(label);if(typeof message?.content==='string'){const text=document.createElement('pre');text.className='message-text';text.textContent=message.content;box.append(text)}else box.append(readable(message?.content??message));const extras={...message};delete extras.role;delete extras.content;if(Object.keys(extras).length)box.append(readable(extras))}}
function renderCallDetail(data){
  const c=(data.model_calls||[]).find(x=>x.request_id===$('model-call').value),input=$('model-input'),output=$('model-output'),validation=$('model-validation'),diagnostics=$('model-diagnostics');
  input.replaceChildren();output.replaceChildren();validation.replaceChildren();diagnostics.replaceChildren();
  if(!c){input.textContent='No recorded model call for this stage.';output.textContent='No recorded model call for this stage.';return}
  renderMessages(input,c.messages);
  const title=document.createElement('h3');title.textContent=`${c.node_id} · attempt ${c.attempt} · call ${c.call_index} · ${c.status}`;diagnostics.append(title);
  const pre=document.createElement('pre');pre.className='message-text';pre.textContent=c.raw_response??'No response was received.';output.append(pre);
  const findings=c.findings?.length?c.findings:c.audit?.findings||[],phase=c.audit?.phase;
  const summary=document.createElement('strong');summary.textContent=`Validation: ${phase|| (findings.length?'failed':c.status)} · ${findings.length} finding${findings.length===1?'':'s'}`;validation.append(summary);
  for(const f of findings){const row=document.createElement('div');row.className='finding';row.textContent=typeof f==='string'?f:[f.code,f.instance_location,f.problem,f.required_correction].filter(Boolean).join(' · ')||JSON.stringify(f);validation.append(row)}
  if(c.parsed!=null)detailField(diagnostics,'Parsed result (not the raw response)',c.parsed);
  if(c.audit)detailField(diagnostics,'Validation audit',c.audit);
  if(c.effective_model)detailField(diagnostics,'Configured provider / model / reasoning',c.effective_model);
  if(c.response_metadata)detailField(diagnostics,'Provider metadata / usage',c.response_metadata);
  if(c.error)detailField(diagnostics,'Failure',c.error);
  const dispatches=(data.physical_calls||[]).filter(p=>p.request_id===c.request_id);
  if(dispatches.length)detailField(diagnostics,'Transport dispatches / retries',dispatches)
}
function renderRetryDetail(data){
  const box=$('retry-detail');box.replaceChildren();
  const [kind,id]=$('retry-select').value.split(':');
  const r=kind==='repair'?(data.repairs||[]).find(x=>x.repair_id===id):(data.semantic_revisions||[]).find(x=>x.link_id===id);
  if(!r){box.textContent='No repair or revision recorded.';return}
  const card=document.createElement('div');card.className='inspect-card';
  const title=document.createElement('h3');title.textContent=kind==='repair'?`Output repair ${r.repair_ordinal}/${r.frozen_limit} · ${r.node_id} · attempt ${r.attempt}`:`Semantic revision ${r.revision_ordinal}/${r.frozen_limit} · ${r.checker_id} → ${r.target_id}`;
  card.append(title);
  detailField(card,'Outcome and cause',{outcome:r.outcome,audit_phase:r.audit_phase,created:r.created,feedback_issued:r.feedback_issued});
  const failed=(data.model_calls||[]).find(c=>c.request_id===r.failed_call_id||(kind==='semantic'&&c.node_id===r.target_id&&c.attempt===r.failed_target_attempt));
  if(failed)detailField(card,'Failed model response',failed.raw_response??'No response was received.');
  const correction=document.createElement('section');correction.className='repair-correction';
  const heading=document.createElement('h4');heading.textContent='Validation and correction';correction.append(heading);
  detailField(correction,'Validation findings',r.findings??[]);
  detailField(correction,r.feedback_issued===false?'Corrective feedback recorded (not dispatched)':'Corrective feedback recorded',r.rendered_feedback??'No corrective feedback recorded.');
  card.append(correction);
  const next=(data.model_calls||[]).find(c=>c.request_id===r.next_request_id||(kind==='semantic'&&c.node_id===r.target_id&&c.attempt===r.next_target_attempt));
  if(next)detailField(card,'Next model result',{status:next.status,raw_response:next.raw_response,parsed_response:next.parsed});
  box.append(card)
}
