function renderReview(data){const r=data.run,out=data.artifacts?.[r.snapshot?.workflow?.output];$('rhs-review-tab').disabled=!['waiting_review','completed','rejected','blocked'].includes(r.status);const targets=r.snapshot?.workflow?.revision_targets||[r.snapshot?.workflow?.revision_target].filter(Boolean);const prior=$('review-target').value;$('review-target').replaceChildren(...targets.map(x=>new Option(x,x)));if(targets.includes(prior))$('review-target').value=prior;$('approve').disabled=r.status!=='waiting_review';const omissions=r.omission_policy?.omitted_fact_ids||[];$('omission-ack-label').hidden=!omissions.length;$('omission-ack').checked=$('omission-ack').dataset.run===r.id&&$('omission-ack').dataset.revision===String(out?.revision)&&$('omission-ack').checked;$('omission-ack').dataset.run=r.id;$('omission-ack').dataset.revision=String(out?.revision);$('delete-run').hidden=['running','pending','waiting_model'].includes(r.status);$('resume').hidden=r.status!=='failed'||!r.error?.recovery_action;$('resume').textContent=r.error?.recovery_action==='explicit_external_retry'?'Retry provider request (may repeat)':'Resume execution';$('copy-legacy').hidden=!r.legacy;$('self-panel').hidden=!(developer&&r.status==='waiting_model'&&data.handoff);if(!$('self-panel').hidden)$('handoff').textContent=structured(data.handoff);rhs('clinical',activeRhsTab)}
