function renderRunFiles(data){const box=$('run-files');box.replaceChildren();const path=data.paths?.run_folder;if(!path)return;const copy=document.createElement('button');copy.type='button';copy.className='quiet mini';copy.textContent='Copy run path';copy.onclick=async()=>{try{await navigator.clipboard.writeText(path);copy.textContent='Path copied'}catch(_){showError(new Error('Clipboard access is unavailable; copy the displayed run path manually.'),false)}};box.append(copy);for(const [label,rel,available] of [['Input','input.json',true],['Frozen config','run-config/resolved.json',true],['Current output','output.md',!!data.artifacts?.[data.run.snapshot?.workflow?.output]]]){if(!available)continue;const a=document.createElement('a');a.className='file-link';a.href=`/api/runs/${encodeURIComponent(data.run.id)}/download/${rel.split('/').map(encodeURIComponent).join('/')}`;a.textContent=`Download ${label}`;box.append(a)}}
function renderUserInput(run,box){box.replaceChildren();const input=run.input||{},wf=run.snapshot?.manifest?.id;let text=null;if(wf==='clinical_letter'){const sources=input.sources||[];if(sources.length===1&&typeof sources[0].content==='string')text=sources[0].content}else if(wf==='guideline_qa'&&typeof input.question==='string')text=input.question;const heading=document.createElement('h2');heading.textContent=run.origins?.task_input==='user_supplied'?'User input':'Recorded run input';box.append(heading);const pre=document.createElement('div');pre.className='user-input-text';pre.textContent=text??'This run has structured input; see its recorded fields below.';box.append(pre);if(wf==='clinical_letter'&&input.purpose){const label=run.snapshot?.selected_purpose?.label||run.snapshot?.purposes?.options?.find(x=>x.id===input.purpose)?.label||input.purpose;const p=document.createElement('p');p.textContent=`Purpose: ${label}`;box.append(p)}if(text===null){const raw=document.createElement('pre');raw.textContent=structured(input);box.append(raw)}}
