  current=data;const r=data.run;$('result-title').textContent=r.title||r.snapshot?.manifest?.name||'Run';updateActivity(data);$('dev-status').textContent=statusLabel(r,data);$('provenance').textContent=`Run ${r.id} · created ${new Date((r.created||0)*1000).toLocaleString()}`;renderRunFiles(data);renderUsage(data.usage||{});renderSteps(r,data);renderExecution(data);$('dev-steps').replaceChildren(...[...$('steps').children].map(x=>x.cloneNode(true)));$('dev-progress').replaceChildren(Object.assign(document.createElement('progress'),{value:data.execution?.reached_count||0,max:data.execution?.total||1}));$('dev-usage').textContent=structured(data.usage||{});renderUserInput(r,$('run-input'));renderUserInput(r,$('dev-run-input'));renderOutput(data);renderFacts(data);renderChecks(data);renderConflicts(data);renderReview(data);renderDevReview(data);populateInspector(data);$('artifacts').textContent=structured(data.artifacts||{});if(data.current_error)showError({error:data.current_error},true);else clearError(true)
