async function refresh(target=rid,generation=selectionGeneration){if(!target)return;try{const data=await api('/api/runs/'+encodeURIComponent(target));if(target!==rid||generation!==selectionGeneration||data.run_id!==rid)return;const rev=Number(data.inspection_revision||0),seen=newestRevision.get(target)??-1;if(rev<seen)return;if(rev>seen||!current||current.run_id!==target){newestRevision.set(target,rev);render(data)}else updateActivity(data);$('last-refresh').textContent=`Last refreshed ${new Date().toLocaleTimeString()}`;$('poll-status').hidden=true;clearTimeout(pollTimer);if(['pending','running','waiting_model','waiting_review'].includes(data.run.status))pollTimer=setTimeout(()=>refresh(target,generation),900)}catch(e){if(target!==rid||generation!==selectionGeneration)return;$('poll-status').hidden=false;$('poll-status').textContent=`Live refresh failed: ${e.data?.error?.explanation||e.message}. Displayed run state may be stale.`;clearTimeout(pollTimer);pollTimer=setTimeout(()=>refresh(target,generation),1800)}}

async function review(decision,omissionAction=false){const r=current.run,out=current.artifacts?.[r.snapshot?.workflow?.output];const payload={review_request_id:crypto.randomUUID(),revision:out?.revision??null,actor:$('actor').value,decision,comments:$('comments').value};if(decision==='approve'){const omitted=r.omission_policy?.omitted_fact_ids||[];if(omitted.length&&!$('omission-ack').checked)throw new Error('Acknowledge the previously applied omissions before approval.');payload.acknowledged_omission_ids=omitted;payload.acknowledged_conflict_ids=[...document.querySelectorAll('[data-conflict]:checked')].map(x=>x.dataset.conflict)}else if(decision==='revise'){payload.target=omissionAction?'draft':$('review-target').value;if(r.status==='blocked')payload.expected_block={code:r.block.code,node_id:r.block.node_id,attempt:r.block.attempt};if(r.snapshot?.manifest?.id==='clinical_letter'&&payload.target==='draft'){payload.omissions=[...document.querySelectorAll('[data-fact]:checked')].map(x=>({fact_id:x.dataset.fact,reason:document.querySelector(`[data-reason="${CSS.escape(x.dataset.fact)}"]`).value,extraction_revision:r.active?.facts}));if(payload.omissions.some(x=>!x.reason.trim()))throw new Error('Give a reason for each omitted fact.')}if(omissionAction&&!payload.omissions.length)throw new Error('Select at least one fact to omit.')}await api(`/api/runs/${encodeURIComponent(rid)}/review`,payload);await refresh(rid,selectionGeneration)}
async function devReview(decision){const r=current.run,out=current.artifacts?.[r.snapshot?.workflow?.output],checked=[...$('dev-review-omissions').querySelectorAll('[data-dev-fact]:checked')];const payload={review_request_id:crypto.randomUUID(),revision:out?.revision??null,actor:$('dev-actor').value,decision,comments:$('dev-comments').value};if(decision==='approve'){payload.acknowledged_omission_ids=checked.map(x=>x.dataset.devFact);payload.acknowledged_conflict_ids=[...$('dev-review-conflicts').querySelectorAll('[data-dev-conflict]:checked')].map(x=>x.dataset.devConflict)}if(decision==='revise'){payload.target=$('dev-review-target').value;if(r.status==='blocked')payload.expected_block={code:r.block.code,node_id:r.block.node_id,attempt:r.block.attempt};if(r.snapshot?.manifest?.id==='clinical_letter'&&payload.target==='draft')payload.omissions=checked.map(x=>({fact_id:x.dataset.devFact,reason:$('dev-review-omissions').querySelector(`[data-dev-reason="${CSS.escape(x.dataset.devFact)}"]`).value,extraction_revision:r.active?.facts}))}await api(`/api/runs/${encodeURIComponent(rid)}/review`,payload);await refresh(rid,selectionGeneration)}

async function setDeveloper(){const selector=$('workspace-selector');selector.disabled=true;try{const r=await api('/api/developer-mode',{enabled:selector.value==='developer'});developer=r.developer_enabled;$('advanced-option').hidden=!developer;if(!developer&&$('input-mode').value==='advanced')$('input-mode').value='free_text';switchWorkspace(developer?'developer':'clinical');showInputs();if(developer){await loadSteps();await loadFixtures()}if(rid)await refresh(rid,selectionGeneration)}finally{try{const state=await api('/api/session');developer=state.developer_enabled;switchWorkspace(developer?'developer':'clinical')}finally{selector.disabled=false}}}
async function reconcileWorkspace(){const state=await api('/api/session');if(state.developer_enabled!==developer){developer=state.developer_enabled;$('advanced-option').hidden=!developer;switchWorkspace(developer?'developer':'clinical');if(rid)await refresh(rid,selectionGeneration)}}
window.addEventListener('focus',()=>reconcileWorkspace().catch(showError));
async function loadSteps(){if(!developer)return;const w=$('step-workflow').value||workflow();steps=await api('/api/dev/workflows/'+encodeURIComponent(w)+'/steps');const prev=$('step').value;$('step').replaceChildren(...steps.map(x=>new Option(x.id,x.id)));if(steps.some(x=>x.id===prev))$('step').value=prev;else if(steps[0])$('step').value=steps[0].id;const profileRows=await api('/api/model-profiles?workflow_id='+encodeURIComponent(w));$('step-profile').replaceChildren(...profileRows.map(p=>new Option(p.name,p.id)));renderStepHelp();await loadFixtures()}
function renderStepHelp(){const s=steps.find(x=>x.id===$('step').value);$('step-help').textContent=s?`${s.purpose} Required input and output contracts are validated before/after execution. Output schema: ${JSON.stringify(s.output_schema)}`:'Select a stage.'}
