function schemaTemplate(schema){if(!schema||typeof schema!=='object')return null;if(schema.default!==undefined)return schema.default;if(schema.const!==undefined)return schema.const;if(schema.enum?.length)return schema.enum[0];if(schema.type==='object'||schema.properties){const o={};for(const k of schema.required||[])o[k]=schemaTemplate(schema.properties?.[k]||{});return o}if(schema.type==='array')return [];if(schema.type==='string')return '';if(schema.type==='integer'||schema.type==='number')return schema.minimum??0;if(schema.type==='boolean')return false;return null}
function baseFixture(resolved){return {fixture_schema_version:1,id:$('fixture-id').value,version:Number($('fixture-version').value),workflow_id:$('step-workflow').value||workflow(),node_id:$('step').value,step_contract_version:1,resolved_inputs:resolved,evidence_snapshots:[],context:{feedback:null,review_decisions:[]},provenance:{source_run_id:null,source_node_attempt:null},data_suitability:'synthetic',origins:{task_input:'synthetic',evidence:{},revision_feedback:{}}}}
async function newFixture(){const s=steps.find(x=>x.id===$('step').value);if(!s)throw new Error('Select a stage first.');$('fixture').value=JSON.stringify(baseFixture(schemaTemplate(s.input_schema)||{}),null,2);$('fixture-source').value='interactive';$('fixture-result').textContent='Created schema-shaped input. Complete required fields before running.'}
async function chooseSavedFixture(){const value=$('fixture-existing').value;if(!value)return;const [id,v]=value.split('|');const row=fixtures.find(x=>x.id===id&&String(x.version)===v);if(!row)throw new Error('fixture_not_found');$('fixture').value=JSON.stringify(row.document,null,2);$('fixture-id').value=row.id;$('fixture-version').value=row.version;$('fixture-source').value='saved'}
async function captureStep(){if(!rid||!current)throw new Error('Select a run first.');const node=$('step').value,attempt=current.run.attempts?.[node];if(!attempt)throw new Error('No attempt for selected stage.');const doc=await api('/api/dev/fixtures/capture',{run_id:rid,node_id:node,attempt});doc.id=$('fixture-id').value;doc.version=Number($('fixture-version').value);$('fixture').value=JSON.stringify(doc,null,2);$('fixture-source').value='prior'}
async function saveFixture(){const doc=parseJson('fixture');doc.id=$('fixture-id').value;doc.version=Number($('fixture-version').value);const r=await api('/api/dev/fixtures',{fixture:doc});$('fixture-result').textContent='Saved '+r.path;await loadFixtures()}
async function deleteFixture(){const id=$('fixture-id').value,v=Number($('fixture-version').value);await api(`/api/dev/fixtures/${encodeURIComponent(id)}?version=${v}`,undefined,'DELETE');$('fixture-result').textContent=`Deleted scratch ${id} v${v}`;await loadFixtures()}
async function promoteFixture(){const id=$('fixture-id').value,v=Number($('fixture-version').value);const r=await api(`/api/dev/fixtures/${encodeURIComponent(id)}/promote`,{version:v,new_id:$('promote-id').value,new_version:Number($('promote-version').value),suitability:$('fixture-suitability').value,acknowledge_reviewed:$('promote-ack').checked,actor:$('promote-actor').value});$('fixture-result').textContent='Promoted '+r.path;await loadFixtures()}
async function runStep(){const fixture=parseJson('fixture');const payload={workflow_id:$('step-workflow').value||workflow(),node_id:$('step').value,profile_id:$('step-profile').value,fixture,configuration_source:$('configuration-source').value};const tape=parseJson('tape',null);if(tape)payload.tape=tape;const o=retryOverrides();if(Object.keys(o).length)payload.retry_overrides=o;const r=await api('/api/dev/step-runs',payload);selectRun(r.id);await refresh(r.id,selectionGeneration)}
async function submitSelf(){const h=current.handoff||JSON.parse($('handoff').textContent);await api(`/api/dev/runs/${encodeURIComponent(rid)}/handoff`,{contract_version:h.contract_version,request_id:h.request_id,content:$('self-response').value});$('self-response').value='';await refresh(rid,selectionGeneration)}
async function importGuideline(){const file=$('guideline-file').files[0];if(!file)throw new Error('Select a source file.');if(file.size>1024*1024)throw new Error('File too large.');const ext=file.name.split('.').pop().toLowerCase();if(!['json','md','txt'].includes(ext))throw new Error('Unsupported source format.');const content=await file.text();const sources=ext==='json'?JSON.parse(content):[{id:'uploaded',title:file.name,format:ext==='md'?'markdown':'text',content}];const set=$('dev-guideline-set').value||'demo';const result=await api(`/api/dev/guideline-sets/${encodeURIComponent(set)}/import`,{sources,profile_id:$('dev-profile').value});$('guideline-import-result').textContent=yamlValue(result);if(result.run_id){selectRun(result.run_id);await refresh(result.run_id,selectionGeneration)}}
async function copyLegacy(){const r=await api(`/api/runs/${encodeURIComponent(rid)}/copy-input`,{});copyInputId=r.copy_input_id;$('workflow').value=r.workflow_id;await chooseWorkflow();if(![...$('input-mode').options].some(x=>x.value==='copied'))$('input-mode').append(new Option('Copied historical input','copied'));$('input-mode').value='copied';$('copied-preview').textContent=yamlValue(r.input);showInputs();window.scrollTo({top:0,behavior:'smooth'})}

$('workflow').onchange=guard(async()=>{summaryGeneration++;await chooseWorkflow();$('run-workflow-filter').value=workflow();historyDates()});$('run-workflow-filter').onchange=()=>historyDates();$('run-date-filter').onchange=historyTitles;$('run-select').onchange=()=>{if($('run-select').value){selectRun($('run-select').value);refresh(rid,selectionGeneration).catch(showError)}};$('model-stage').onchange=()=>{selectedCall='';renderExecution(current)};$('model-call').onchange=()=>{selectedCall=$('model-call').value;renderCallDetail(current)};$('retry-select').onchange=()=>{selectedRetry=$('retry-select').value;renderRetryDetail(current)};for(const tab of ['input','output','retries','details'])$(`tab-${tab}`).onclick=()=>inspectionTab(tab);$('profile').onchange=showProfile;$('input-mode').onchange=showInputs;$('guideline-set').onchange=guard(()=>showVersions());$('step').onchange=guard(async()=>{renderStepHelp();await loadFixtures()});$('step-workflow').onchange=guard(loadSteps);$('fixture-existing').onchange=guard(chooseSavedFixture);
$('save-profile').onclick=guard(saveProfile);$('verify').onclick=guard(verifyProvider);$('start').onclick=guard(startRun);$('workspace-selector').onchange=guard(setDeveloper);$('dev-workflow').onchange=guard(chooseDevWorkflow);$('dev-guideline-set').onchange=guard(chooseDevVersions);$('dev-input-mode').onchange=showDevInputs;$('dev-generate').onclick=guard(startDevRun);for(const n of ['full','step','guidelines'])$(`dev-tab-${n}`).onclick=()=>showDevPane(n);
$('new-fixture').onclick=guard(newFixture);$('run-step').onclick=guard(runStep);$('capture-step').onclick=guard(captureStep);$('save-fixture').onclick=guard(saveFixture);$('delete-fixture').onclick=guard(deleteFixture);$('promote-fixture').onclick=guard(promoteFixture);$('guideline-import').onclick=guard(importGuideline);$('submit-self').onclick=guard(submitSelf);$('copy-legacy').onclick=guard(copyLegacy);
$('resume').onclick=guard(async()=>{const uncertain=current?.run?.error?.code==='external_response_unknown';if(uncertain&&!window.confirm('The provider may have completed and billed the previous request. Retry it anyway?'))return;await api(`/api/runs/${encodeURIComponent(rid)}/resume`,uncertain?{acknowledge_external_retry:true}:{});await refresh(rid,selectionGeneration)});$('delete-run').onclick=guard(async()=>{await api(`/api/runs/${encodeURIComponent(rid)}`,undefined,'DELETE');rid=null;current=null;$('output').textContent='';await listRuns()});for(const d of ['approve','revise','reject'])$(d).onclick=guard(()=>review(d));$('apply-omissions').onclick=guard(()=>review('revise',true));$('dismiss-error').onclick=()=>clearError(true);
for(const d of ['approve','revise','reject'])$(`dev-${d}`).onclick=guard(()=>devReview(d));
$('inspect-stage').onchange=()=>{selectedInspector.stage=$('inspect-stage').value;selectedInspector.attempt='';selectedInspector.item='';populateAttempts(current)};$('inspect-attempt').onchange=()=>{selectedInspector.attempt=$('inspect-attempt').value;selectedInspector.item='';populateItems(current)};$('inspect-call').onchange=()=>{selectedInspector.item=$('inspect-call').value;renderInspector(current)};
for(const tab of ['input','output']){ $(`rhs-${tab}-tab`).onclick=()=>rhs('clinical',tab);$(`dev-${tab}-tab`).onclick=()=>rhs('developer',tab) }$('rhs-review-tab').onclick=()=>rhs('clinical','review');
for(const format of ['yaml','json'])$(`view-${format}`).onclick=()=>{inspectorFormat=format;if(current)render(current)};

(async()=>{const ss=await api('/api/session');token=ss.csrf;developer=ss.developer_enabled;$('advanced-option').hidden=!developer;apps=await api('/api/applications');$('workflow').replaceChildren(...apps.map(x=>new Option(x.name,x.id)));$('dev-workflow').replaceChildren(...apps.map(x=>new Option(x.name,x.id)));$('step-workflow').replaceChildren(...apps.map(x=>new Option(x.name,x.id)));await chooseWorkflow();await chooseDevWorkflow();showInputs();await pollSummaries();switchWorkspace(developer?'developer':'clinical');$('workspace-selector').disabled=false})().catch(showError);
